declare var angular : ng.IAngularStatic;

const module = angular.module("irtech.netcity.school.socialpassportreports",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components"
	]);

import { SocialPassportReportsRepository } from "./socialpassportreports.repository";
import { ReportsRepository } from "../reports/reports.repository";
import { SocialPassportReportComponent } from "./report/socialpassportreport.component";

/*@ngInject*/
const config = ($routeProvider, $locationProvider : ng.ILocationProvider) => {
	$routeProvider
		.otherwise({
			templateUrl: SocialPassportReportComponent.templateUrl,
			controller: SocialPassportReportComponent.controller,
			controllerAs: SocialPassportReportComponent.controllerAs
		});

	$locationProvider.hashPrefix("");
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
}

module
	.service("socialPassportReportsRepository", SocialPassportReportsRepository)
	.service("reportsRepository", ReportsRepository)
	.config(config);



