"use strict";

import { AppLoader } from "approot/global/apploader";
import { DownloadService } from "approot/global/common.module";
import { PageContext, AppContext } from "approot/global/services/context";
import { SocialPassportReportsRepository } from "../socialpassportreports.repository";
import { ReportsRepository, GenerateReportOptions, ReportOutputType, PreparedReport } from "../../reports/reports.repository";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { TaskQueueService } from "approot/global/services/queue/taskqueue.service";
import { QueueExecutionOptions } from "approot/global/services/queue/taskqueue.model";
import { FilterPanelSettings, IFilterPanel, FilterContext, FilterStatus } from "approot/global/components/filterpanel/filterpanel.model";
import { ReportCtrl } from "../../reports/report/report.component";

interface JQueryPrintUtils<TElement extends Element = HTMLElement> extends JQuery<TElement> {
	printUtils()
}

interface JQueryPrintUtilsStatic extends JQueryStatic {
	<TElement extends Element = HTMLElement>(selector: string): JQueryPrintUtils<TElement>;
}

declare var $: JQueryPrintUtilsStatic;

export enum SocialPassportCategory {
	SocialPassportFullReportExcel = -1,
	FamilyCategory = 1,
	DeviantStudent = 2,
	DeviantFamily = 3,
	ParentsEducationLevel = 4,
	NationalCompositionOfStudents = 5
}

export class SocialPassportReportCtrl extends ReportCtrl {
	public canBeGenerated: boolean = false;
	private title: string;

	/*@ngInject*/
	constructor(
		private $scope: ng.IScope,
		pageContext: PageContext,
		language,
		appContext: AppContext,
		private socialPassportReportsRepository: SocialPassportReportsRepository,
		reportsRepository: ReportsRepository,
		$dialogs: DialogsService,
		taskQueueService: TaskQueueService,
		downloadService: DownloadService,
		$appLoader: AppLoader,
		$routeParams: any) {
		super(pageContext, language, appContext, reportsRepository, $dialogs, taskQueueService, downloadService, $appLoader, $routeParams);

		const reportFpUrl = this.socialPassportReportsRepository.getReportInitFiltersUrl();

		this.filterPanelSettings = {
			url: reportFpUrl,
			styles: {
				compact: false
			},
			events: {
				ready: () => this.onReady(),
				emptyChoice: () => {
					this.emptyChoice = true;
					this.$appLoader.hide();
				}
			}
		}
	}

	public init(pageContext: PageContext) {
		pageContext.parent = null;

		this.title = "Социальный паспорт класса и школы";
		pageContext.title = this.title;
	}

	public getReportTitle() {
		return this.title;
	}


	public getReportId() {
		if (this.filterPanel == null) {
			return SocialPassportCategory.FamilyCategory.toString();
		}

		return SocialPassportCategory[this.filterPanel.getCtxValues().filter(x => (x.filterId == 'category'))[0].filterValue];
	}

	public onReady() {
		// скрывает кнопки генерации кроме excel
		this.canBeGenerated = this.filterPanel.getCtxValues().filter(x => (x.filterId == 'category' || x.filterId == 'subcategory') && x.filterValue == '-1').length === 0;

		this.emptyChoice = false;
		this.$appLoader.hide();

		this.$scope.$applyAsync();
	}
}


export const SocialPassportReportComponent = {
	controller: SocialPassportReportCtrl,
	controllerAs: "ctrl",
	templateUrl: "/static/dist/app/school/socialpassportreports/report/socialpassportreport.component.html"
}


